from taf.nms.nom.schemas.base import SchemaObject, SchemaField, SchemaObjects


class OperationStatusResponse(SchemaObject):
    operation_id = SchemaField(name="operation_id", not_null=True)
    timestamp = SchemaField(name="timestamp", not_null=True)
    status = SchemaField(name="status", not_null=True)

    def __init__(self, operation_id, timestamp, status):
        self.operation_id = operation_id
        self.timestamp = timestamp
        self.status = status

        super(OperationStatusResponse, self).__init__()


class OperationStatusResponses(SchemaObjects):
    schema = OperationStatusResponse
